CREATE SCHEMA IF NOT EXISTS result_service;

-- ============================================================
-- Table: result
-- ============================================================
-- IDs are UUID v7, generated by the application (UuidV7Generator) before insert.
-- No DEFAULT gen_random_uuid() — the database never assigns IDs.
CREATE TABLE result_service.result (
    id                  UUID PRIMARY KEY,
    tenant_id           VARCHAR(255) NOT NULL,
    candidate_id        UUID NOT NULL,
    exam_id             UUID NOT NULL,
    total_score         NUMERIC(10,2) NOT NULL,
    section_scores_json JSONB,
    overall_rank        INTEGER,
    overall_percentile  NUMERIC(6,3),
    scorecard_pdf_ref   VARCHAR(500),
    digi_locker_pushed  BOOLEAN NOT NULL DEFAULT FALSE,
    created_at          TIMESTAMP NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMP NOT NULL DEFAULT NOW(),
    version             BIGINT NOT NULL DEFAULT 0
);

CREATE INDEX idx_result_tenant_id ON result_service.result(tenant_id);
CREATE INDEX idx_result_candidate_id ON result_service.result(candidate_id);
CREATE INDEX idx_result_exam_id ON result_service.result(exam_id);
